/**
 * ───────────────────────────────────────────────────────────────────────────────
 * [shadcn registry item · 教学演示件] AI 回答安全态 AI Answer States
 *
 * 来源:uiux-atlas src/content/entries/components/ai-answer-states/demo/Demo.tsx
 *       (由 scripts/generate-registry.mjs 内联生成;源文件保持不动,重跑生成器即刷新)
 *
 * 诚实标注:这是教学演示件,不是生产组件。原 demo 依赖的三个 @/ 内部模块
 * (@/lib/store 参数 store、@/lib/types 类型、@/components/DemoStage 演示舞台)
 * 在 registry 消费端不可用,已原位改写为「[registry 改写]」注释;文件体内对应的
 * getEntryStore / EntrySchema / DemoStage 引用需按各注释提示替换后,本文件才可编译运行。
 * 它记录的是「本站条目页如何实时驱动参数」,供阅读与改写,不可直接安装即用。
 *
 * 依赖:仅 react(+宿主的 react-dom 渲染);registry item 的 dependencies 留空,
 * 由消费端项目按自身版本声明 react。
 * ───────────────────────────────────────────────────────────────────────────────
 */
import { useEffect, useRef, useState } from "react";
// [registry 改写] 原:import { getEntryStore } from "@/lib/store"; —— 本站内部参数 store(getEntryStore,演示页参数面板 → 舞台的实时数据源),registry 消费端不可用;接入时请改为本地受控 state(useState + props),文件体内的 getEntryStore / store.get / store.subscribe 调用需同步替换。
// [registry 改写] 原:import type { EntrySchema } from "@/lib/types"; —— 本站条目 schema 的 TS 类型(EntrySchema),registry 消费端不可用;接入时请以你自己的参数定义类型内联替代,文件体内的 EntrySchema 注解需同步替换。
// [registry 改写] 原:import DemoStage from "@/components/DemoStage"; —— 本站演示舞台组件(.demo-stage:cssVar 注入点 + 舞台铭牌 + #s= 分享参数恢复),registry 消费端不可用;接入时请以自有舞台容器(如一个 <div>)替代,文件体内的 <DemoStage> 标签需同步替换。

interface DemoProps {
  entryId: string;
  schema: EntrySchema;
}

type Scenario = "normal" | "refusal" | "error";

const SCENARIOS: { id: Scenario; label: string }[] = [
  { id: "normal", label: "正常回答 Normal" },
  { id: "refusal", label: "拒答 Refusal" },
  { id: "error", label: "出错 Error" },
];

/* 引用数据:结构化 citations 数组(Anthropic Citations / OpenAI url_citation 同构),
   cited_text 为精确支撑段落(官方语义:不计入输出 token)。 */
const SOURCES = [
  { title: "Streamdown Docs — Security", url: "https://streamdown.ai/docs/security", quote: "out-of-bounds links rewrite to the default origin and render as [blocked]" },
  { title: "Anthropic — Citations API", url: "https://docs.claude.com/en/docs/build-with-claude/citations", quote: "cited_text quotes the exact supporting passage and is not counted as output tokens" },
];

/* 官方说明:explanation 文案不稳定,展示而非解析(Anthropic 原文 display it rather than parse it) */
const REFUSAL_EXPLANATION =
  "抱歉,我无法协助完成该请求。Sorry, I can't help with that request.";

const PARTIAL = "这个方案的第一步是先解除锁底滚动,然后再将 token 节流上调到 50ms,接下来我们可";

const BODY_BEFORE = "两个官方依据支持这个结论:块级 memo 让已完成段落稳定";
const BODY_AFTER = ",而锁底滚动必须可在当帧被打断(NN/g)。";

const css = `
.ans-wrap { width: min(560px, calc(100% - 24px)); position: relative; }
.ans-tabs { display: flex; gap: 6px; margin-bottom: 10px; flex-wrap: wrap; }
.ans-tab {
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-elev);
  color: var(--text-1);
  font: inherit;
  font-size: 12px;
  padding: 4px 12px;
  cursor: pointer;
}
.ans-tab[aria-pressed="true"] { border-color: var(--accent); color: var(--accent); background: color-mix(in srgb, var(--accent) 10%, transparent); }
.ans-tab:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.ans-card {
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-elev);
  padding: 14px 16px;
  font-size: 13px;
  line-height: 1.75;
  color: var(--text-1);
}
.ans-card.refusal { border-left: 3px solid color-mix(in srgb, var(--accent) 70%, var(--text-1)); }
.ans-badge {
  display: inline-block;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: var(--text-1);
  margin-bottom: 8px;
}
/* 流中部分输出:降权示灰 + 不完整标注(官方:视为不完整应丢弃) */
.ans-partial { opacity: 0.45; }
.ans-partial[data-keep="false"] { text-decoration: line-through; }
.ans-incomplete { display: block; margin-top: 2px; font-size: 11px; color: var(--text-faint); }
.ans-error-text { font-family: var(--font-mono, ui-monospace, monospace); font-size: 12.5px; }
.ans-actions { display: flex; gap: 8px; margin-top: 10px; }
.ans-actions button {
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-elev);
  color: var(--text-1);
  font: inherit;
  font-size: 12px;
  padding: 4px 14px;
  cursor: pointer;
}
.ans-actions button:hover { border-color: var(--accent); color: var(--accent); }
.ans-actions button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* 引用角标:数字编号,不只靠颜色承载 */
.ans-ref {
  border: 0;
  background: none;
  padding: 0 1px;
  font: inherit;
  font-size: 11px;
  color: var(--accent);
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.ans-ref:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; border-radius: 3px; }
/* 悬停/展开来源卡(角标档):含多来源轮播 prev/next + 索引 */
.ans-hovercard {
  margin: 8px 0 0;
  border: 1px dashed var(--border);
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 12px;
  color: var(--text-dim, var(--text-1));
}
.ans-hovercard .t { color: var(--text-1); font-weight: 600; }
.ans-hovercard .q { display: block; margin-top: 2px; font-size: 11.5px; color: var(--text-faint); }
.ans-nav { display: inline-flex; gap: 6px; margin-top: 6px; }
.ans-nav button {
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-elev);
  color: var(--text-1);
  font: inherit;
  font-size: 11px;
  padding: 2px 8px;
  cursor: pointer;
}
.ans-nav button:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.ans-nav .idx { font-family: var(--font-mono, ui-monospace, monospace); font-size: 11px; color: var(--text-faint); align-self: center; }
/* 来源卡(折叠):details/summary 原生语义,键盘可达 */
.ans-sources { margin: 10px 0 0; }
.ans-sources summary {
  cursor: pointer;
  font-size: 12.5px;
  color: var(--text-dim, var(--text-1));
}
.ans-sources summary:hover { color: var(--accent); }
.ans-sources summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }
.ans-sources ul { margin: 6px 0 0; padding-left: 18px; font-size: 12px; }
.ans-sources a { color: var(--accent); text-underline-offset: 2px; }
.ans-footnote { margin: 8px 0 0; padding-left: 18px; font-size: 11.5px; color: var(--text-faint); }
.ans-footnote a { color: var(--accent); }
/* 免责声明:官方无规定(未证实)——demo 提供尾注/来源下方/不展示三档 */
.ans-disclaimer { margin: 10px 0 0; font-size: 11px; color: var(--text-faint); }
/* 链接安全弹窗:跳转前展示完整 URL(Streamdown rehype-harden 语义) */
.ans-modal {
  margin: 10px 0 0;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 12px;
  background: var(--bg);
}
.ans-modal .url {
  display: block;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 11px;
  color: var(--text-dim, var(--text-1));
  overflow-wrap: anywhere;
  margin: 4px 0 6px;
}
.ans-status { margin: 8px 2px 0; font-size: 12px; color: var(--text-faint); }
.ans-hint { margin: 8px 2px 0; font-size: 12px; color: var(--text-faint); }
`;

/**
 * AI 回答安全态演示:三场景切换(正常/拒答/出错)。
 * citationMode / carouselEnabled / refusalRetry / midStreamRefusalPolicy /
 * linkSafetyModal / disclaimerPosition 全部为 JS 型参数(订阅 store),无 CSS 变量型参数。
 * 拒答档先流式吐出部分文字,refusal 信号到达后按官方语义处理(展示不解析/丢弃部分输出)。
 */
export default function Demo({ entryId, schema }: DemoProps) {
  const store = getEntryStore(entryId, schema);
  const [citationMode, setCitationMode] = useState(() => store.get("citationMode") as string);
  const [carousel, setCarousel] = useState(() => store.get("carouselEnabled") as string);
  const [retryMode, setRetryMode] = useState(() => store.get("refusalRetry") as string);
  const [midStreamPolicy, setMidStreamPolicy] = useState(() => store.get("midStreamRefusalPolicy") as string);
  const [linkModal, setLinkModal] = useState(() => store.get("linkSafetyModal") as string);
  const [disclaimer, setDisclaimer] = useState(() => store.get("disclaimerPosition") as string);

  const [scenario, setScenario] = useState<Scenario>("normal");
  const [partialLen, setPartialLen] = useState(0);
  const [refusalArrived, setRefusalArrived] = useState(false);
  const [openBadge, setOpenBadge] = useState<number | null>(null);
  const [carouselIdx, setCarouselIdx] = useState(0);
  const [pendingUrl, setPendingUrl] = useState<string | null>(null);
  const timerRef = useRef<number | undefined>(undefined);

  useEffect(
    () =>
      store.subscribe(() => {
        setCitationMode(store.get("citationMode") as string);
        setCarousel(store.get("carouselEnabled") as string);
        setRetryMode(store.get("refusalRetry") as string);
        setMidStreamPolicy(store.get("midStreamRefusalPolicy") as string);
        setLinkModal(store.get("linkSafetyModal") as string);
        setDisclaimer(store.get("disclaimerPosition") as string);
      }),
    [store],
  );

  const reset = () => {
    if (timerRef.current !== undefined) window.clearTimeout(timerRef.current);
    setPartialLen(0);
    setRefusalArrived(false);
    setOpenBadge(null);
    setPendingUrl(null);
  };

  // 拒答场景:先流式吐出部分输出 → refusal 信号到达(官方:流中拒答,部分输出视为不完整)
  useEffect(() => {
    reset();
    if (scenario !== "refusal") return;
    if (partialLen === 0) {
      timerRef.current = window.setTimeout(() => setPartialLen(4), 300);
    } else if (partialLen < PARTIAL.length) {
      timerRef.current = window.setTimeout(() => {
        setPartialLen((n) => Math.min(n + 4, PARTIAL.length));
      }, 40);
    }
    return reset;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scenario, partialLen]);

  useEffect(() => {
    if (scenario === "refusal" && partialLen >= PARTIAL.length && !refusalArrived) {
      setRefusalArrived(true);
    }
  }, [scenario, partialLen, refusalArrived]);

  const sources = carousel === "on" ? SOURCES : SOURCES.slice(0, 1);
  const cardSource = sources[carouselIdx % sources.length];
  const disclaimerText = "本段内容由 AI 生成,引用与结论请以来源原文为准。";

  const handleSourceClick = (e: React.MouseEvent, url: string) => {
    e.preventDefault();
    if (linkModal === "on") setPendingUrl(url);
    else setPendingUrl(null);
  };

  return (
    <DemoStage entryId={entryId} schema={schema}>
      <div className="ans-wrap">
        <div className="ans-tabs" role="group" aria-label="场景选择 Scenario">
          {SCENARIOS.map((s) => (
            <button
              type="button"
              key={s.id}
              className="ans-tab"
              aria-pressed={scenario === s.id}
              onClick={() => setScenario(s.id)}
            >
              {s.label}
            </button>
          ))}
        </div>

        {scenario === "normal" && (
          <article className="ans-card" role="status">
            <p style={{ margin: 0 }}>
              {BODY_BEFORE}
              {citationMode === "footnote" ? (
                <sup id="ans-fn-1">[1]</sup>
              ) : (
                <button
                  type="button"
                  className="ans-ref"
                  aria-expanded={openBadge === 0}
                  onClick={() => setOpenBadge(openBadge === 0 ? null : 0)}
                >
                  [1]
                </button>
              )}
              {BODY_AFTER}
              {citationMode !== "sources-card" && (
                <>
                  {" "}
                  四闸之外链接一律重写
                  <button
                    type="button"
                    className="ans-ref"
                    aria-expanded={openBadge === 1}
                    onClick={() => setOpenBadge(openBadge === 1 ? null : 1)}
                  >
                    [2]
                  </button>
                  。
                </>
              )}
            </p>

            {citationMode === "inline-hover" && openBadge !== null && (
              <div className="ans-hovercard">
                <span className="t">{cardSource.title}</span>
                <a href={cardSource.url} onClick={(e) => handleSourceClick(e, cardSource.url)}>
                  {cardSource.url}
                </a>
                <span className="q">cited_text:{cardSource.quote}</span>
                {carousel === "on" && sources.length > 1 && (
                  <span className="ans-nav">
                    <button
                      type="button"
                      aria-label="上一来源 Previous source"
                      onClick={() => setCarouselIdx((i) => (i - 1 + sources.length) % sources.length)}
                    >
                      ‹
                    </button>
                    <span className="idx">{carouselIdx % sources.length + 1}/{sources.length}</span>
                    <button
                      type="button"
                      aria-label="下一来源 Next source"
                      onClick={() => setCarouselIdx((i) => (i + 1) % sources.length)}
                    >
                      ›
                    </button>
                  </span>
                )}
              </div>
            )}

            {citationMode === "sources-card" && (
              <details className="ans-sources">
                <summary>Used {SOURCES.length} sources</summary>
                <ul>
                  {SOURCES.map((s) => (
                    <li key={s.url}>
                      <a href={s.url} onClick={(e) => handleSourceClick(e, s.url)}>{s.title}</a>
                    </li>
                  ))}
                </ul>
              </details>
            )}

            {citationMode === "footnote" && (
              <ol className="ans-footnote">
                <li id="ans-fn-1-ref">
                  <a href={SOURCES[0].url} onClick={(e) => handleSourceClick(e, SOURCES[0].url)}>{SOURCES[0].title}</a> — {SOURCES[0].quote}
                </li>
                <li>
                  <a href={SOURCES[1].url} onClick={(e) => handleSourceClick(e, SOURCES[1].url)}>{SOURCES[1].title}</a> — {SOURCES[1].quote}
                </li>
              </ol>
            )}

            {disclaimer === "message-footer" && <p className="ans-disclaimer">{disclaimerText}</p>}
            {disclaimer === "sources-below" && citationMode === "sources-card" && (
              <p className="ans-disclaimer">{disclaimerText}</p>
            )}

            {pendingUrl && (
              <div className="ans-modal" role="alertdialog" aria-label="链接安全确认 Link safety">
                即将离开站内,完整 URL:Full URL before navigation:
                <span className="url">{pendingUrl}</span>
                <div className="ans-actions">
                  <button type="button" onClick={() => setPendingUrl(null)}>继续访问 Continue</button>
                  <button type="button" onClick={() => setPendingUrl(null)}>取消 Cancel</button>
                </div>
              </div>
            )}
          </article>
        )}

        {scenario === "refusal" && (
          <article className="ans-card refusal" role="status">
            <span className="ans-badge">stop_reason: refusal · cyber</span>
            {partialLen > 0 && (
              <div className="ans-partial" data-keep={midStreamPolicy === "keep-partial" ? "true" : "false"}>
                {PARTIAL.slice(0, partialLen)}
                {refusalArrived && midStreamPolicy === "discard-partial" && (
                  <span className="ans-incomplete">部分输出已丢弃(官方:视为不完整)Partial discarded — officially incomplete</span>
                )}
                {refusalArrived && midStreamPolicy === "keep-partial" && (
                  <span className="ans-incomplete">保留部分输出(反面教材)Partial kept — the anti-pattern</span>
                )}
              </div>
            )}
            {refusalArrived && (
              <>
                <p style={{ margin: "8px 0 0" }}>{REFUSAL_EXPLANATION}</p>
                <p className="ans-incomplete">explanation 原文展示、不解析 displayed verbatim, never parsed</p>
                <div className="ans-actions">
                  {retryMode === "regenerate" && <button type="button">重新生成 Retry (regenerate)</button>}
                  {retryMode === "fallback" && <button type="button">备用模型重试 Fallback model</button>}
                </div>
                {retryMode === "none" && <p className="ans-incomplete">无重试出口(反面教材)No retry exit — the anti-pattern</p>}
              </>
            )}
          </article>
        )}

        {scenario === "error" && (
          <article className="ans-card" role="status">
            <span className="ans-badge">error</span>
            <p className="ans-error-text" style={{ margin: "4px 0 0" }}>Something went wrong.</p>
            <p className="ans-incomplete">通用文案防服务端信息泄漏(官方建议)Generic text prevents server-detail leaks (official advice)</p>
            <div className="ans-actions">
              {retryMode !== "none" && <button type="button">重试 Retry (regenerate)</button>}
            </div>
          </article>
        )}

        <p className="ans-status" aria-live="polite">
          {scenario === "normal"
            ? `引用档 citationMode: ${citationMode}${citationMode === "inline-hover" ? ` · 轮播 carousel: ${carousel}` : ""} · 免责位 disclaimer: ${disclaimer}`
            : scenario === "refusal"
              ? refusalArrived
                ? `流中拒答已处理 · 策略 policy: ${midStreamPolicy} · 出口 exit: ${retryMode}`
                : "回答流式中,refusal 信号即将到达 Streaming — refusal incoming"
              : `错误态 error · 出口 exit: ${retryMode}`}
        </p>
        <p className="ans-hint">
          正常档点角标看来源卡;拒答档看部分输出的丢弃与 explanation 原文;链接点开先见完整 URL · Normal: tap a badge for the source card; refusal: watch the partial discard and the verbatim explanation; links reveal the full URL first
        </p>
      </div>
      <style>{css}</style>
    </DemoStage>
  );
}
